/**
 * WhatsApp handoff — FR-10, FR-11, FR-13, FR-14 · §9.5.
 *
 * Invariants (unit-tested):
 *  - URL stays under 2000 chars, and degrades rather than throwing (no dead
 *    ends, product principle 3);
 *  - `whatsappNumber` is digits only — never "+"/spaces;
 *  - a missing discount code omits the line entirely (no "undefined" text);
 *  - structure is identical across placements; only values differ.
 */

import type { HandoffContext } from "./types";

export const MAX_PAYLOAD_URL_LENGTH = 2000;

const E164_DIGITS = /^\d{8,15}$/;

const QR_GREETING = "Hi Danga! I'm enquiring from your QR code.";
const DIRECT_GREETING =
  "Hi Danga! I'd like to know more about your available properties.";

/**
 * The agent reads this verbatim, so it must be grammatical plain language
 * (FR-11). Non-QR visitors get the generic greeting — Flow E must not claim a
 * QR scan that never happened.
 */
export function buildMessage(ctx: HandoffContext): string {
  if (ctx.route !== "qr") return DIRECT_GREETING;

  const lines = [QR_GREETING, `Placement: ${ctx.placement}`];
  if (ctx.discountCode) {
    lines.push(
      `My ${ctx.config.discountPercent}% QR discount code: ${ctx.discountCode}`,
    );
  }
  return lines.join("\n");
}

export function buildShortLink(whatsappNumber: string): string {
  return `https://wa.me/${whatsappNumber}`;
}

export function buildWhatsAppUrl(ctx: HandoffContext): string {
  const number = ctx.config.whatsappNumber;
  const text = encodeURIComponent(buildMessage(ctx));
  const url = `${buildShortLink(number)}?text=${text}`;
  // Degrade instead of throwing: a long payload must never break the funnel.
  return url.length >= MAX_PAYLOAD_URL_LENGTH ? buildShortLink(number) : url;
}

/** FR-13 — "Message us on WhatsApp" button on the web client. */
export function buildWebWhatsAppUrl(ctx: HandoffContext): string {
  const number = ctx.config.whatsappNumber;
  return `https://web.whatsapp.com/send?phone=${number}&text=${encodeURIComponent(buildMessage(ctx))}`;
}

/** Config guard used at build time (AD-9) and defensively before rendering. */
export function isValidWhatsAppNumber(number: string): boolean {
  return E164_DIGITS.test(number);
}
