import type { Metadata } from "next";

import { BannerInjector } from "@/components/BannerInjector";
import { Handoff } from "@/components/Handoff";
import { Hero } from "@/components/Hero";
import { SiteFooter } from "@/components/SiteFooter";
import { SiteHeader } from "@/components/SiteHeader";
import { config } from "@/config";
import { landing } from "@/data/content/landing";
import { site } from "@/data/content/site";
import { buildWhatsAppUrl } from "@/lib/whatsapp";

export const metadata: Metadata = {
  title: site.homeTitle,
};

/**
 * Organic entry point (Flow E). Deliberately renders NO discount markup —
 * the `BannerInjector` injects the banner only for sessions whose cookie says
 * the visitor arrived via a QR code (FR-15 acceptance criteria).
 *
 * The CTA ships a server-rendered `href` so it works with JavaScript off
 * (C-7); `Handoff` upgrades it on mount if attribution says `route=qr`.
 */
export default function HomePage() {
  const baseHref = buildWhatsAppUrl({
    placement: "",
    discountCode: null,
    route: "direct",
    config: {
      whatsappNumber: config.NEXT_PUBLIC_WHATSAPP_NUMBER,
      discountPercent: config.NEXT_PUBLIC_DISCOUNT_PERCENT,
    },
  });

  return (
    <>
      <BannerInjector />
      <SiteHeader />
      <Hero>
        <Handoff
          placement=""
          baseHref={baseHref}
          ctaLocation="landing"
          label={landing.ctaLabel}
          className="inline-flex w-full items-center justify-center rounded-2xl bg-emerald-700 px-6 py-4 text-base font-semibold text-white shadow-sm outline-offset-2 hover:bg-emerald-800 focus-visible:outline focus-visible:outline-2 focus-visible:outline-emerald-600 sm:w-auto"
        />
      </Hero>
      <SiteFooter />
    </>
  );
}
